// Des: Commands run, export, canary with the safety ladder
// Flo: dry-run prints plan and worst-case cost > --live runs the walker / export / canary fetches > print result > exit code
// I/O: Ctx (parsed args, config, data dir) > stdout text or JSON, files for export, exit code
// ===================================================================
const std = @import("std"); const cx = @import("ct-ctrl-ctxz.zig"); const walk = @import("ru-page-walk.zig"); const expo = @import("ct-expo-data.zig"); const exit = @import("ct-exit-code.zig"); const cana = @import("ru-cana-chec.zig"); const pipe = @import("ru-page-fetc.zig"); const file = @import("st-stor-file.zig"); const inde = @import("st-page-inde.zig"); const base = @import("nt-vend-base.zig"); const spen = @import("ru-spen-guar.zig"); const cfgz = @import("cf-conf-load.zig"); const clou = @import("ct-ctrl-clou.zig"); const hash = @import("ut-hash-dedu.zig");
const CF = .{ .seeb = 4 << 20, .rawd = "raw", .part = ".part", .revz = 1000 };
pub const Est = struct { cred: u32, micr: u64 };
pub fn estWorst(conf: cfgz.Conf, geoz: []const u8) Est { const vend = base.vendFind(conf.vend_orde[0]) orelse return .{ .cred = 0, .micr = 0 }; var cred: u32 = 0; for ([_]base.Mode{ .plain, .rend, .prem }) |mode| cred += base.credReq(vend, .{ .urlz = "", .mode = mode, .geoz = if (geoz.len > 0) geoz else conf.geoz_code_dflt }); return .{ .cred = cred, .micr = @as(u64, cred) * spen.priceOf(conf, vend) }; }
const Dryz = struct { mode: []const u8, seeds: usize, sitemap: bool, tier1: []const u8, worst_cred_url: u32, worst_micr_url: u64, note: []const u8 };
fn seedRead(ctx: *const cx.Ctx) ![]const []const u8 { var list: std.ArrayList([]const u8) = .empty; if (ctx.args.urlz.len > 0) try list.append(ctx.allo, ctx.args.urlz); if (ctx.args.seed.len > 0) { const text = std.Io.Dir.cwd().readFileAlloc(ctx.iozz, ctx.args.seed, ctx.allo, .limited(CF.seeb)) catch return error.BadUsage; var iter = std.mem.splitScalar(u8, text, '\n'); while (iter.next()) |raws| { const line = std.mem.trim(u8, raws, " \t\r"); if (line.len == 0 or line[0] == '#') continue; try list.append(ctx.allo, line); } } return list.toOwnedSlice(ctx.allo); }
pub fn runRun(ctx: *const cx.Ctx) !u8 { const seeds = try seedRead(ctx); if (seeds.len == 0 and ctx.args.smap.len == 0 and !cx.dbHave(ctx)) return error.BadUsage;
if (!ctx.args.live) { const est = estWorst(ctx.conf, ctx.args.geoz); const dry: Dryz = .{ .mode = "dry-run", .seeds = seeds.len, .sitemap = ctx.args.smap.len > 0, .tier1 = "own GET first, free", .worst_cred_url = est.cred, .worst_micr_url = est.micr, .note = "vendors only when own GET is blocked, only inside free credits unless --live --force; add --live to run" }; try cx.outz(ctx, try cx.jsonOr(ctx, dry, try std.fmt.allocPrint(ctx.allo, "dry-run | {d} seeds | worst case per URL {d} credits ({d} micro-USD) | add --live to run", .{ seeds.len, est.cred, est.micr }))); return 0; }
var dbzz = try cx.dbOpen(ctx); defer dbzz.close(); var real = try cx.realMake(ctx); var wlk = walk.Walk.init(ctx.init.gpa, ctx.iozz, ctx.conf, &dbzz, ctx.dirz, false); defer wlk.deinit(); wlk.back = real.backend(); wlk.go = ctx.args.forc; wlk.geoz = ctx.args.geoz; wlk.foll = ctx.args.foll; _ = try wlk.walkSeed(seeds); if (ctx.args.smap.len > 0) _ = try wlk.walkSmap(ctx.args.smap); _ = try wlk.walkRevi(CF.revz); const sum = try wlk.walkRun(if (ctx.args.decl > 0) ctx.args.decl else null);
const plain = try std.fmt.allocPrint(ctx.allo, "run | seen {d} done {d} fail {d} skip {d} blocked {d} dead {d} {s}{s}", .{ sum.seen, sum.done, sum.fail, sum.skip, sum.blok, sum.dead, if (sum.halt) "HALTED " else "", if (sum.incm) "INCOMPLETE" else "" }); if (sum.halt) clou.alertTry(ctx, "scra run halted", "circuit breaker tripped or spend stopped; check scra status"); try cx.outz(ctx, try cx.jsonOr(ctx, sum, plain)); return exit.sumCode(sum.done, sum.fail, sum.blok, sum.dead, sum.halt, sum.incm); }
pub fn runExpo(ctx: *const cx.Ctx) !u8 { const fmt: expo.Fmt = if (std.mem.eql(u8, ctx.args.fmtz, "csv")) .csv else if (std.mem.eql(u8, ctx.args.fmtz, "jsonl")) .jsonl else return error.BadUsage; if (!cx.dbHave(ctx)) { try cx.outz(ctx, "no data yet"); return 0; } var dbzz = try cx.dbOpen(ctx); defer dbzz.close(); var wbuf: [8192]u8 = undefined;
if (ctx.args.outz.len == 0) { var wtr = std.Io.File.stdout().writerStreaming(ctx.iozz, &wbuf); _ = try expo.expoRun(&dbzz, &wtr.interface, fmt, ctx.allo); return 0; }
const temp = try std.fmt.allocPrint(ctx.allo, "{s}{s}", .{ ctx.args.outz, CF.part }); const cwdz = std.Io.Dir.cwd(); var fil = try cwdz.createFile(ctx.iozz, temp, .{}); var wtr = fil.writer(ctx.iozz, &wbuf); const cnt = expo.expoRun(&dbzz, &wtr.interface, fmt, ctx.allo) catch |err| { fil.close(ctx.iozz); return err; }; fil.close(ctx.iozz); try cwdz.rename(temp, cwdz, ctx.args.outz, ctx.iozz); try cx.outz(ctx, try std.fmt.allocPrint(ctx.allo, "exported {d} rows to {s}", .{ cnt, ctx.args.outz })); return 0; }
const Cres = struct { urlz: []const u8, stat: []const u8, why: []const u8 };
fn sigOf(ctx: *const cx.Ctx, out: pipe.Outc) !cana.Sig { if (out.hexz.len != 64) return error.Fail; var hexz: hash.Hexz = undefined; @memcpy(&hexz, out.hexz[0..64]); const rawd = try std.fs.path.join(ctx.allo, &.{ ctx.dirz, CF.rawd }); const body = try file.fileLoad(ctx.allo, ctx.iozz, rawd, hexz, ctx.conf.fetc_body_maxz); return cana.sigMake(ctx.allo, body); }
pub fn runCana(ctx: *const cx.Ctx) !u8 { const live = ctx.args.live; if (ctx.args.adds.len > 0) { if (!live) { try cx.outz(ctx, "dry-run | would fetch the URL and store its baseline signature | add --live to run"); return 0; } var dbzz = try cx.dbOpen(ctx); defer dbzz.close(); const out = try pipe.pageFetc(ctx.init.gpa, ctx.allo, ctx.iozz, ctx.conf, &dbzz, ctx.dirz, ctx.args.adds, false); const code = exit.outcCode(out.stat, out.code); if (code != 0 or out.hexz.len == 0) return if (code == 0) 1 else code; try cana.canaSet(&dbzz, ctx.allo, out.urlz, try sigOf(ctx, out), pipe.nowMs(ctx.iozz)); try cx.outz(ctx, try std.fmt.allocPrint(ctx.allo, "baseline saved: {s}", .{out.urlz})); return 0; }
if (!cx.dbHave(ctx)) { try cx.outz(ctx, "no canaries yet: scra canary --add <url> --live"); return 0; } var dbzz = try cx.dbOpen(ctx); defer dbzz.close(); const all = try cana.canaAll(&dbzz, ctx.allo); if (!live) { try cx.outz(ctx, try std.fmt.allocPrint(ctx.allo, "dry-run | {d} canary URLs | add --live to run", .{all.len})); return 0; }
var res: std.ArrayList(Cres) = .empty; var drift: u32 = 0; var failz: u32 = 0; for (all) |item| { const out = pipe.pageFetc(ctx.init.gpa, ctx.allo, ctx.iozz, ctx.conf, &dbzz, ctx.dirz, item.urlz, false) catch |err| { failz += 1; try res.append(ctx.allo, .{ .urlz = item.urlz, .stat = "fail", .why = @errorName(err) }); continue; }; if (exit.outcCode(out.stat, out.code) != 0 or out.hexz.len == 0) { failz += 1; try res.append(ctx.allo, .{ .urlz = item.urlz, .stat = "fail", .why = out.stat }); continue; } const cur = sigOf(ctx, out) catch { failz += 1; try res.append(ctx.allo, .{ .urlz = item.urlz, .stat = "fail", .why = "unreadable" }); continue; }; if (cana.sigDrif(item.sig, cur)) |why| { drift += 1; try res.append(ctx.allo, .{ .urlz = item.urlz, .stat = "drift", .why = why }); } else { try res.append(ctx.allo, .{ .urlz = item.urlz, .stat = "ok", .why = "" }); } }
if (ctx.args.json) { try cx.outz(ctx, try std.json.Stringify.valueAlloc(ctx.allo, res.items, .{})); } else { for (res.items) |item| try cx.outz(ctx, try std.fmt.allocPrint(ctx.allo, "{s} | {s} | {s}", .{ item.stat, item.urlz, item.why })); } return exit.canaCode(drift, failz); }
